# Calculate what I think the output should be
def build_output():
    # Copy the structure and transform
    output = []
    for row in range(10):
        new_row = []
        for col in range(10):
            if row == 1 and col in range(5):
                new_row.append(2)  # top horizontal bar of 2
            elif (row in range(3,7) and col == 0):
                new_row.append(2)  # left vertical
            elif row == 7 and col >= 5:
                new_row.append(3)  # right bar
            elif row == 8 and col >= 6:
                new_row.append(6)  # right middle
            elif row == 6 and col == 0:
                new_row.append(2)  # bottom of left vertical
            else:
                new_row.append(0)
        output.append(new_row)
    return output

output = build_output()
